pragma solidity ^0.8.20;

// contract TargetContractVul {
//     /*
//         TRACK FALLBACK EXECUTION
//     */
//     uint256 public fallbackCounter;

//     uint256 public receivedETH;

//     /*
//     =====================================================
//     FALLBACK FUNCTION
//     =====================================================

//     Triggered when:
