// =========================================================
// CALLER CONTRACT
// =========================================================
// */

// contract FallbackCallerVul {
//     /*
//         STORE TARGET ADDRESS
//     */
//     address public target;

//     /*
//         LAST CALL STATUS
//     */
//     bool public lastSuccess;

//     /*
//         CONSTRUCTOR
//     */
//     constructor(address _target)
//     {

//         target = _target;
//     }

//     /*
